/*
 * A001232  Numbers k such that 9*k = (k written backwards), k > 0.
 * https://oeis.org/A001232
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, nonn, nice
 * Formula:   a(n) = 99*A061851(n): m runs through the palindromes made of 0's
 *            and 1's with no singleton runs, in increasing order. They are
 *            generated by unranking with a run-length DP over the first half
 *            of the digits instead of a search
 * Range:     u8 none, u16 n <= 2, u32 n <= 11, u64 n <= 142, u128 n <= 10000,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

#define MAXH 256

seq_t a(idx_t n) {
    static uint64_t c[MAXH + 2][3];
    int digits[2 * MAXH + 2];
    uint64_t k = (uint64_t)(n - 1);
    int L = 2, h = 1, even = 1;

    for (;;) {
        h = (L + 1) / 2;
        even = (L % 2 == 0);
        /* c[pos][r]: completions of positions pos..h-1 (0-based) given the
           current run length r (1, or 2 meaning >= 2) at position pos-1 */
        c[h][1] = even ? 1 : 0;
        c[h][2] = 1;
        for (int pos = h - 1; pos >= 1; pos--) {
            c[pos][1] = c[pos + 1][2];
            c[pos][2] = c[pos + 1][2] + c[pos + 1][1];
        }
        uint64_t total = c[1][1];
        if (k < total) break;
        k -= total;
        L++;
        if ((L + 1) / 2 > MAXH) return 0;
    }

    /* unrank k among half-strings in lexicographic order */
    int cur = 1, r = 1;
    digits[0] = 1;
    for (int pos = 1; pos < h; pos++) {
        /* option "continue": char cur, new run 2; option "switch": char 1-cur, new run 1 */
        uint64_t cc = c[pos + 1][2];
        uint64_t cs = (r == 2) ? c[pos + 1][1] : 0;
        if (cur == 0) {
            /* continue gives '0' first */
            if (k < cc) { r = 2; }
            else { k -= cc; cur = 1; r = 1; }
        } else {
            /* switch gives '0' first */
            if (k < cs) { cur = 0; r = 1; }
            else { k -= cs; r = 2; }
        }
        digits[pos] = cur;
    }
    for (int i = 0; i < h; i++) digits[L - 1 - i] = digits[i];

    seq_t m = 0;
    for (int i = 0; i < L; i++) {
        m = m * 10 + digits[i];
    }
    return m * 99;
}
